#!/usr/bin/env python3
"""A small persistent HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class Store:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            return
        try:
            with self.path.open("r", encoding="utf-8") as source:
                document = json.load(source, parse_constant=self._reject_constant)
            entries = document.get("entries") if isinstance(document, dict) else None
            if not isinstance(entries, dict):
                raise ValueError("top-level 'entries' object is missing")
            now = time.time()
            loaded: dict[str, dict[str, Any]] = {}
            discarded = False
            for key, entry in entries.items():
                if not isinstance(key, str) or not key or "/" in key:
                    discarded = True
                    continue
                if not isinstance(entry, dict) or "value" not in entry:
                    discarded = True
                    continue
                expires_at = entry.get("expires_at")
                if expires_at is not None:
                    if (isinstance(expires_at, bool) or
                            not isinstance(expires_at, (int, float)) or
                            not math.isfinite(expires_at)):
                        discarded = True
                        continue
                    if expires_at <= now:
                        discarded = True
                        continue
                loaded[key] = {"value": entry["value"], "expires_at": expires_at}
            self.entries = loaded
            if discarded:
                self._persist_locked()
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            raise RuntimeError(f"cannot load data file {self.path}: {exc}") from exc

    @staticmethod
    def _reject_constant(value: str) -> None:
        raise ValueError(f"non-finite JSON number: {value}")

    def _remove_expired_locked(self) -> bool:
        now = time.time()
        expired = [
            key for key, entry in self.entries.items()
            if entry["expires_at"] is not None and entry["expires_at"] <= now
        ]
        for key in expired:
            del self.entries[key]
        return bool(expired)

    def _persist_locked(self) -> None:
        parent = self.path.parent
        parent.mkdir(parents=True, exist_ok=True)
        payload = {"entries": self.entries}
        temp_name: str | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", dir=parent,
                prefix=f".{self.path.name}.", suffix=".tmp", delete=False
            ) as output:
                temp_name = output.name
                json.dump(payload, output, ensure_ascii=False, allow_nan=False,
                          separators=(",", ":"), sort_keys=True)
                output.write("\n")
                output.flush()
                os.fsync(output.fileno())
            os.replace(temp_name, self.path)
            temp_name = None
            try:
                directory_fd = os.open(parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                # Directory fsync is unavailable on some platforms/filesystems.
                pass
        finally:
            if temp_name is not None:
                try:
                    os.unlink(temp_name)
                except FileNotFoundError:
                    pass

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            removed = self._remove_expired_locked()
            if removed:
                self._best_effort_persist()
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry["value"])

    def keys(self) -> list[str]:
        with self.lock:
            removed = self._remove_expired_locked()
            if removed:
                self._best_effort_persist()
            return sorted(self.entries)

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            self._remove_expired_locked()
            existed = key in self.entries
            previous = self.entries.get(key)
            expires_at = None if ttl is None else time.time() + ttl
            if expires_at is not None and not math.isfinite(expires_at):
                raise ValueError("ttl_seconds is too large")
            self.entries[key] = {"value": value, "expires_at": expires_at}
            try:
                self._persist_locked()
            except Exception:
                if previous is None:
                    self.entries.pop(key, None)
                else:
                    self.entries[key] = previous
                raise
            return existed

    def delete(self, key: str) -> bool:
        with self.lock:
            self._remove_expired_locked()
            previous = self.entries.pop(key, None)
            if previous is None:
                return False
            try:
                self._persist_locked()
            except Exception:
                self.entries[key] = previous
                raise
            return True

    def compact(self) -> None:
        with self.lock:
            if self._remove_expired_locked():
                self._persist_locked()

    def _best_effort_persist(self) -> None:
        try:
            self._persist_locked()
        except OSError as exc:
            print(f"warning: could not persist expiry cleanup: {exc}", file=sys.stderr)


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store) -> None:
        self.store = store
        super().__init__(address, Handler)


class Handler(BaseHTTPRequestHandler):
    server: Server

    def log_message(self, format: str, *args: Any) -> None:
        print(f"{self.address_string()} - {format % args}", file=sys.stderr)

    def _send_json(self, status: int, value: Any) -> None:
        data = json.dumps(value, ensure_ascii=False, allow_nan=False,
                          separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def _error(self, status: int, message: str) -> None:
        self._send_json(status, {"error": message})

    def _key_from_path(self) -> tuple[str | None, str | None]:
        path = urlsplit(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None, "unknown route"
        encoded = path[len(prefix):]
        if not encoded or "/" in encoded:
            return None, "key must be non-empty and must not contain '/'"
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except (UnicodeDecodeError, ValueError):
            return None, "key must be valid URL-encoded UTF-8"
        if not key or "/" in key:
            return None, "key must be non-empty and must not contain '/'"
        return key, None

    def _read_json(self) -> Any:
        if self.headers.get("Transfer-Encoding"):
            raise RequestError(400, "transfer encoding is not supported")
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            raise RequestError(411, "Content-Length is required")
        try:
            length = int(raw_length)
        except ValueError:
            raise RequestError(400, "invalid Content-Length") from None
        if length < 0:
            raise RequestError(400, "invalid Content-Length")
        if length > MAX_BODY:
            raise RequestError(413, "request body exceeds 1 MiB limit")
        body = self.rfile.read(length)
        if len(body) != length:
            raise RequestError(400, "incomplete request body")
        try:
            return json.loads(body.decode("utf-8"), parse_constant=Store._reject_constant)
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
            raise RequestError(400, "malformed JSON") from None

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        if path == "/health":
            self._send_json(200, {"status": "ok"})
            return
        if path == "/v1/keys":
            self._send_json(200, {"keys": self.server.store.keys()})
            return
        key, error = self._key_from_path()
        if error:
            self._error(404 if error == "unknown route" else 400, error)
            return
        found, value = self.server.store.get(key)
        if not found:
            self._error(404, "key not found")
            return
        self._send_json(200, {"key": key, "value": value})

    def do_PUT(self) -> None:
        key, error = self._key_from_path()
        if error:
            self._error(404 if error == "unknown route" else 400, error)
            return
        try:
            document = self._read_json()
            if not isinstance(document, dict) or "value" not in document:
                raise RequestError(400, "body must be an object containing 'value'")
            unknown = set(document) - {"value", "ttl_seconds"}
            if unknown:
                raise RequestError(400, "body contains unknown fields")
            ttl = document.get("ttl_seconds")
            if ttl is not None and (
                isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or
                not math.isfinite(ttl) or ttl <= 0
            ):
                raise RequestError(400, "ttl_seconds must be finite and greater than zero")
            replaced = self.server.store.put(key, document["value"], ttl)
        except RequestError as exc:
            self._error(exc.status, exc.message)
            return
        except ValueError as exc:
            self._error(400, str(exc))
            return
        except (OSError, TypeError) as exc:
            self.log_error("persistence failure: %s", exc)
            self._error(500, "could not persist data")
            return
        self._send_json(200 if replaced else 201, {"key": key, "value": document["value"]})

    def do_DELETE(self) -> None:
        key, error = self._key_from_path()
        if error:
            self._error(404 if error == "unknown route" else 400, error)
            return
        try:
            deleted = self.server.store.delete(key)
        except OSError as exc:
            self.log_error("persistence failure: %s", exc)
            self._error(500, "could not persist data")
            return
        if not deleted:
            self._error(404, "key not found")
            return
        self.send_response(204)
        self.end_headers()

    def _method_not_allowed(self) -> None:
        self.send_response(405)
        self.send_header("Allow", "GET, PUT, DELETE")
        data = b'{"error":"method not allowed"}'
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    do_POST = _method_not_allowed
    do_PATCH = _method_not_allowed
    do_OPTIONS = _method_not_allowed
    do_HEAD = _method_not_allowed

# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON HTTP service with TTLs and atomic on-disk
persistence.

## Run

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Using `--port 0` selects a free port. The process prints
`LISTENING <actual-port>` to stdout once it is ready; diagnostics go to stderr.

## API

```sh
curl -X PUT http://127.0.0.1:8080/v1/kv/example \
  -H 'Content-Type: application/json' \
  -d '{"value":{"answer":42},"ttl_seconds":60}'
curl http://127.0.0.1:8080/v1/kv/example
curl http://127.0.0.1:8080/v1/keys
curl -X DELETE http://127.0.0.1:8080/v1/kv/example
curl http://127.0.0.1:8080/health
```

Keys are URL-encoded UTF-8 path segments. They may contain spaces but cannot be
empty or contain `/`. Request bodies are limited to 1 MiB. The data file is
replaced atomically after each mutation; send SIGTERM or press Ctrl-C for a
clean shutdown.

